<script lang="ts">
  import { page } from '$app/stores';
  import { onMount } from 'svelte';
  import { api } from '$lib/api/client';
  import type { Experiment } from '$lib/types/api';
  import StatePanel from '$lib/components/StatePanel.svelte';
  import { formatTime } from '$lib/utils/format';
  let item: Experiment | undefined, loading = true, error = '';
  $: duration = item?.started_at && item?.ended_at ? Math.max(0, Date.parse(item.ended_at) - Date.parse(item.started_at)) : undefined;
  $: durationLabel = duration == null ? 'In progress' : duration < 60_000 ? `${Math.round(duration / 1000)}s` : `${Math.round(duration / 60_000)}m`;
  async function load() { loading = true; error = ''; try { item = await api.experiment($page.params.id || ''); } catch (e) { error = e instanceof Error ? e.message : 'Unable to load experiment'; } finally { loading = false; } }
  onMount(load);
</script>

<svelte:head><title>{item?.name || 'Experiment'} · Temporal RCA</title></svelte:head>

{#if loading}<StatePanel state="loading" title="Loading run dossier…" />{:else if error}<StatePanel state="error" message={error} retry={load} />{:else if item}
  <a class="back mono" href="/experiments">← All experiments</a>
  <div class="heading"><div><span class="eyebrow">{item.scenario || 'Ground-truth run'}</span><h1 class="display">{item.name}</h1><p>Evidence capture dossier for a controlled system scenario.</p></div><span class="state" class:running={item.status === 'running'} class:completed={item.status === 'completed'} class:failed={item.status === 'failed'}><i aria-hidden="true">{item.status === 'completed' ? '✓' : item.status === 'running' ? '●' : item.status === 'failed' ? '!' : '◇'}</i>{item.status}</span></div>
  <section class="run-overview panel"><div class="overview-head"><div><span class="eyebrow">Run overview</span><strong>Ground truth and telemetry alignment</strong></div><span class="mono run-id">{item.id}</span></div><div class="facts"><div><span class="eyebrow">Started</span><b class="mono">{item.started_at ? formatTime(item.started_at) : 'Not started'}</b></div><div><span class="eyebrow">Ended</span><b class="mono">{item.ended_at ? formatTime(item.ended_at) : 'Awaiting completion'}</b></div><div><span class="eyebrow">Duration</span><b class="mono">{durationLabel}</b></div><div><span class="eyebrow">Scenario</span><b>{item.scenario || 'Experiment'}</b></div></div></section>
  <section class="next-step"><div><span class="eyebrow">Evidence actions</span><h2>Follow the signal through the stack</h2><p>Open the synchronized frame to compare system, service and process telemetry around this run.</p></div><div class="actions"><a class="button primary" href={`/timeline?filters=experiment_id:${item.id}`}>Correlate signals <span>→</span></a><a class="button" href={`/api/v1/experiments/${item.id}/export`}>Download evidence <span>↓</span></a></div></section>
{/if}

