x-width:570px; color:var(--muted); font-size:12px; line-height:1.5; }.actions { display:flex; flex-shrink:0; gap:7px; }.actions .button { min-height:35px; font-size:11px; }.actions .button span { font-size:14px; }
  @media (max-width:700px) { .heading { align-items:flex-start; }.heading h1 { font-size:35px; }.heading p { line-height:1.45; }.facts { grid-template-columns:repeat(2,1fr); }.facts div:nth-child(2) { border-right:0; }.facts div:nth-child(-n+2) { border-bottom:1px solid var(--line); }.next-step { display:block; }.actions { flex-direction:column; margin-top:16px; }.actions .button { width:100%; } } @media (max-width:420px) { .overview-head { align-items:flex-start; flex-direction:column; }.run-id { max-width:100%; }.facts { grid-template-columns:1fr; }.facts div,.facts div:nth-child(2) { border-right:0; border-bottom:1px solid var(--line); }.facts div:last-child { border-bottom:0; } }
